let rawLog = msg.payload;

const WASOS_LABEL = global.get("wasosLabel");
const PARAT_BRIDGE_LABEL = global.get("paratBridgeLabel");

if (!WASOS_LABEL || !PARAT_BRIDGE_LABEL) {
    node.warn("Labels er ikke satt i global context");
    return null;
}

msg.payload = rawLog.map(({
    text,
    loggedByFullName,
    client
}) => ({
    text: `[${client}] ${loggedByFullName}: ${text}`,
    keyEvent: false,
    releasedInfo: false,
    labels: client === "wasos" ? [WASOS_LABEL] : []
}));

return msg;
